INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000722', 'Cutoff dalam evaluasi formasi digunakan untuk...', 'Cutoffs in formation evaluation are used to...', 'option', 'PFC000000005', 'Inisialisasi', 'a:4:{i:0;s:26:"Menghitung kedalaman sumur";i:1;s:20:"Menentukan warna log";i:2;s:51:"Menentukan batas nilai agar zona dianggap produktif";i:3;s:18:"Mengukur laju alir";}', 'a:4:{i:0;s:20:"Calculate well depth";i:1;s:20:"Determine log colors";i:2;s:66:"Define the value thresholds for a zone to be considered productive";i:3;s:17:"Measure flow rate";}', '', 'Menentukan batas nilai agar zona dianggap produktif', 'Define the value thresholds for a zone to be considered productive', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000723', 'Net pay adalah bagian reservoir yang...', 'Net pay is the part of the reservoir that...', 'option', 'PFC000000005', 'Inisialisasi', 'a:4:{i:0;s:21:"Selalu mengandung air";i:1;s:52:"Memenuhi cutoff dan mengandung hidrokarbon produktif";i:2;s:30:"Berada di atas permukaan tanah";i:3;s:22:"Memiliki porositas nol";}', 'a:4:{i:0;s:21:"Always contains water";i:1;s:54:"Meets the cutoffs and contains productive hydrocarbons";i:2;s:27:"Is above the ground surface";i:3;s:17:"Has zero porosity";}', '', 'Memenuhi cutoff dan mengandung hidrokarbon produktif', 'Meets the cutoffs and contains productive hydrocarbons', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000724', 'Rw adalah simbol untuk...', 'Rw is the symbol for...', 'option', 'PFC000000005', 'Inisialisasi', 'a:4:{i:0;s:24:"Resistivitas air formasi";i:1;s:25:"Resistivitas batuan total";i:2;s:19:"Resistivitas lumpur";i:3;s:17:"Kadar air terikat";}', 'a:4:{i:0;s:27:"Formation water resistivity";i:1;s:22:"Total rock resistivity";i:2;s:15:"Mud resistivity";i:3;s:19:"Bound water content";}', '', 'Resistivitas air formasi', 'Formation water resistivity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000725', 'Plot silang (crossplot) neutron-density paling sering digunakan untuk...', 'The neutron-density crossplot is most often used to...', 'option', 'PFC000000005', 'Inisialisasi', 'a:4:{i:0;s:42:"Identifikasi litologi dan koreksi efek gas";i:1;s:27:"Menghitung kedalaman casing";i:2;s:28:"Menentukan tekanan reservoir";i:3;s:22:"Mengukur laju produksi";}', 'a:4:{i:0;s:45:"Identify lithology and correct for gas effect";i:1;s:22:"Calculate casing depth";i:2;s:28:"Determine reservoir pressure";i:3;s:23:"Measure production rate";}', '', 'Identifikasi litologi dan koreksi efek gas', 'Identify lithology and correct for gas effect', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000726', 'Zona dengan saturasi air 100% (Sw = 1) berarti zona tersebut...', 'A zone with 100% water saturation (Sw = 1) means the zone...', 'option', 'PFC000000005', 'Inisialisasi', 'a:4:{i:0;s:34:"Terisi air seluruhnya (water zone)";i:1;s:18:"Merupakan zona gas";i:2;s:24:"Terisi minyak seluruhnya";i:3;s:24:"Tidak memiliki porositas";}', 'a:4:{i:0;s:37:"Is entirely water-filled (water zone)";i:1;s:13:"Is a gas zone";i:2;s:22:"Is entirely oil-filled";i:3;s:15:"Has no porosity";}', '', 'Terisi air seluruhnya (water zone)', 'Is entirely water-filled (water zone)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000727', 'Manakah parameter yang dibutuhkan dalam persamaan Archie untuk menghitung Sw?', 'Which parameters are required in Archie''s equation to calculate Sw?', 'multi', 'PFC000000005', 'Inisialisasi', 'a:4:{i:0;s:15:"Porositas (phi)";i:1;s:25:"Resistivitas formasi (Rt)";i:2;s:29:"Resistivitas air formasi (Rw)";i:3;s:22:"Eksponen sementasi (m)";}', 'a:4:{i:0;s:14:"Porosity (phi)";i:1;s:26:"Formation resistivity (Rt)";i:2;s:32:"Formation water resistivity (Rw)";i:3;s:24:"Cementation exponent (m)";}', '', 'a:4:{i:0;s:15:"Porositas (phi)";i:1;s:25:"Resistivitas formasi (Rt)";i:2;s:29:"Resistivitas air formasi (Rw)";i:3;s:22:"Eksponen sementasi (m)";}', 'a:4:{i:0;s:14:"Porosity (phi)";i:1;s:26:"Formation resistivity (Rt)";i:2;s:32:"Formation water resistivity (Rw)";i:3;s:24:"Cementation exponent (m)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000728', 'Urutkan alur evaluasi formasi dari tahap paling awal.', 'Arrange the formation evaluation workflow from the earliest stage.', 'drag', 'PFC000000005', 'Inisialisasi', 'a:6:{i:0;s:24:"Quality control data log";i:1;s:26:"Penentuan litologi dan Vsh";i:2;s:26:"Perforasi dan uji produksi";i:3;s:21:"Perhitungan porositas";i:4;s:33:"Perhitungan saturasi air (Archie)";i:5;s:40:"Penentuan net pay dan volume hidrokarbon";}', 'a:6:{i:0;s:24:"Log data quality control";i:1;s:31:"Lithology and Vsh determination";i:2;s:31:"Perforation and production test";i:3;s:20:"Porosity calculation";i:4;s:37:"Water saturation calculation (Archie)";i:5;s:44:"Net pay and hydrocarbon volume determination";}', '', 'a:5:{i:0;s:24:"Quality control data log";i:1;s:26:"Penentuan litologi dan Vsh";i:2;s:21:"Perhitungan porositas";i:3;s:33:"Perhitungan saturasi air (Archie)";i:4;s:40:"Penentuan net pay dan volume hidrokarbon";}', 'a:5:{i:0;s:24:"Log data quality control";i:1;s:31:"Lithology and Vsh determination";i:2;s:20:"Porosity calculation";i:3;s:37:"Water saturation calculation (Archie)";i:4;s:44:"Net pay and hydrocarbon volume determination";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000729', 'Benarkah saturasi hidrokarbon dapat dihitung sebagai 1 - Sw?', 'Is it true that hydrocarbon saturation can be calculated as 1 - Sw?', 'yesorno', 'PFC000000005', 'Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000730', 'Diketahui a = 1, Rw = 0,1 ohm-m, phi = 0,2, m = 2, n = 2, dan Rt = 10 ohm-m. Berapa saturasi air (Sw)?', 'Given a = 1, Rw = 0.1 ohm-m, phi = 0.2, m = 2, n = 2, and Rt = 10 ohm-m. What is the water saturation (Sw)?', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:3:"70%";i:1;s:3:"25%";i:2;s:4:"100%";i:3;s:3:"50%";}', 'a:4:{i:0;s:3:"70%";i:1;s:3:"25%";i:2;s:4:"100%";i:3;s:3:"50%";}', '', '50%', '50%', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000731', 'Pada Pickett plot, kemiringan garis lurus (slope) pada skala log-log mencerminkan nilai...', 'On a Pickett plot, the slope of the straight line on log-log scale reflects the value of...', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:2:"Rw";i:1;s:23:"-m (eksponen sementasi)";i:2;s:1:"a";i:3;s:22:"+n (eksponen saturasi)";}', 'a:4:{i:0;s:2:"Rw";i:1;s:25:"-m (cementation exponent)";i:2;s:1:"a";i:3;s:24:"+n (saturation exponent)";}', '', '-m (eksponen sementasi)', '-m (cementation exponent)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000732', 'Nilai eksponen sementasi (m) yang umum untuk batupasir adalah sekitar...', 'The typical cementation exponent (m) for sandstone is about...', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:3:"1,0";i:1;s:3:"5,0";i:2;s:3:"2,0";i:3;s:3:"3,5";}', 'a:4:{i:0;s:3:"1.0";i:1;s:3:"5.0";i:2;s:3:"2.0";i:3;s:3:"3.5";}', '', '2,0', '2.0', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
