INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000734', 'Bulk volume water (BVW) pada zona transisi umumnya...', 'Bulk volume water (BVW) in the transition zone is generally...', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:15:"Relatif konstan";i:1;s:10:"Selalu nol";i:2;s:31:"Bertambah dua kali setiap meter";i:3;s:20:"Tidak dapat dihitung";}', 'a:4:{i:0;s:19:"Relatively constant";i:1;s:11:"Always zero";i:2;s:19:"Doubles every meter";i:3;s:23:"Impossible to calculate";}', '', 'Relatif konstan', 'Relatively constant', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000735', 'Moveable hydrocarbon index (Sxo/Sw) digunakan untuk...', 'The movable hydrocarbon index (Sxo/Sw) is used to...', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:25:"Mengukur salinitas lumpur";i:1;s:49:"Menilai potensi hidrokarbon yang dapat diproduksi";i:2;s:26:"Menghitung kedalaman sumur";i:3;s:27:"Menentukan densitas matriks";}', 'a:4:{i:0;s:20:"Measure mud salinity";i:1;s:43:"Assess the producible hydrocarbon potential";i:2;s:20:"Calculate well depth";i:3;s:24:"Determine matrix density";}', '', 'Menilai potensi hidrokarbon yang dapat diproduksi', 'Assess the producible hydrocarbon potential', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000736', 'Zona dengan porositas rendah, Vsh tinggi, dan Sw tinggi sebaiknya...', 'A zone with low porosity, high Vsh, and high Sw should be...', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:17:"Dianggap zona gas";i:1;s:30:"Dihitung sebagai net pay penuh";i:2;s:36:"Dikeluarkan dari perhitungan net pay";i:3;s:20:"Dianggap zona minyak";}', 'a:4:{i:0;s:21:"Considered a gas zone";i:1;s:23:"Counted as full net pay";i:2;s:37:"Excluded from the net pay calculation";i:3;s:22:"Considered an oil zone";}', '', 'Dikeluarkan dari perhitungan net pay', 'Excluded from the net pay calculation', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000737', 'Koreksi efek gas pada neutron-density dilakukan karena gas...', 'Gas effect correction on neutron-density is performed because gas...', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:26:"Menambah kandungan lempung";i:1;s:68:"Menurunkan pembacaan neutron sehingga porositas terlihat lebih besar";i:2;s:33:"Menghilangkan sinyal resistivitas";i:3;s:26:"Menaikkan densitas matriks";}', 'a:4:{i:0;s:22:"Increases clay content";i:1;s:53:"Lowers the neutron reading so porosity appears larger";i:2;s:30:"Removes the resistivity signal";i:3;s:24:"Increases matrix density";}', '', 'Menurunkan pembacaan neutron sehingga porositas terlihat lebih besar', 'Lowers the neutron reading so porosity appears larger', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000738', 'Resistivitas air formasi (Rw) dapat diestimasi dari kurva SP menggunakan...', 'Formation water resistivity (Rw) can be estimated from the SP curve using...', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:40:"Hubungan defleksi SP dengan rasio Rw/Rmf";i:1;s:15:"Kurva gamma ray";i:2;s:13:"Kurva caliper";i:3;s:9:"Nilai PEF";}', 'a:4:{i:0;s:59:"The relationship between SP deflection and the Rw/Rmf ratio";i:1;s:19:"The gamma ray curve";i:2;s:17:"The caliper curve";i:3;s:13:"The PEF value";}', '', 'Hubungan defleksi SP dengan rasio Rw/Rmf', 'The relationship between SP deflection and the Rw/Rmf ratio', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000739', 'Jika Sw = 60% dan Sxo = 30%, maka zona tersebut...', 'If Sw = 60% and Sxo = 30%, then the zone...', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:28:"Tidak mengandung hidrokarbon";i:1;s:21:"Merupakan zona serpih";i:2;s:48:"Mengandung hidrokarbon mobile yang cukup menarik";i:3;s:21:"Seluruhnya terisi air";}', 'a:4:{i:0;s:24:"Contains no hydrocarbons";i:1;s:15:"Is a shale zone";i:2;s:41:"Contains movable hydrocarbons of interest";i:3;s:24:"Is entirely water-filled";}', '', 'Mengandung hidrokarbon mobile yang cukup menarik', 'Contains movable hydrocarbons of interest', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000740', 'Volume hidrokarbon per satuan volume batuan dihitung dengan...', 'Hydrocarbon volume per unit rock volume is calculated as...', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:8:"phi + Sw";i:1;s:14:"phi x (1 - Sw)";i:2;s:8:"phi x Sw";i:3;s:14:"(1 - phi) x Sw";}', 'a:4:{i:0;s:8:"phi + Sw";i:1;s:14:"phi x (1 - Sw)";i:2;s:8:"phi x Sw";i:3;s:14:"(1 - phi) x Sw";}', '', 'phi x (1 - Sw)', 'phi x (1 - Sw)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000741', 'Pada batupasir lempungan, penggunaan persamaan Archie langsung tanpa koreksi lempung umumnya...', 'In shaly sandstone, using Archie''s equation directly without clay correction generally...', 'option', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:17:"Tidak berpengaruh";i:1;s:35:"Menghasilkan Sw yang terlalu rendah";i:2;s:30:"Menghasilkan porositas negatif";i:3;s:35:"Menghasilkan Sw yang terlalu tinggi";}', 'a:4:{i:0;s:13:"Has no effect";i:1;s:27:"Produces Sw that is too low";i:2;s:26:"Produces negative porosity";i:3;s:28:"Produces Sw that is too high";}', '', 'Menghasilkan Sw yang terlalu tinggi', 'Produces Sw that is too high', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000742', 'Manakah yang termasuk cutoff petrofisika dalam penentuan net pay?', 'Which of the following are petrophysical cutoffs in net pay determination?', 'multi', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:19:"Cutoff harga minyak";i:1;s:16:"Cutoff porositas";i:2;s:19:"Cutoff saturasi air";i:3;s:26:"Cutoff volume serpih (Vsh)";}', 'a:4:{i:0;s:16:"Oil price cutoff";i:1;s:15:"Porosity cutoff";i:2;s:23:"Water saturation cutoff";i:3;s:25:"Shale volume cutoff (Vsh)";}', '', 'a:3:{i:0;s:26:"Cutoff volume serpih (Vsh)";i:1;s:16:"Cutoff porositas";i:2;s:19:"Cutoff saturasi air";}', 'a:3:{i:0;s:25:"Shale volume cutoff (Vsh)";i:1;s:15:"Porosity cutoff";i:2;s:23:"Water saturation cutoff";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000743', 'Manakah penyebab kesalahan dalam perhitungan saturasi air?', 'Which are causes of error in water saturation calculation?', 'multi', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:23:"Warna core yang berbeda";i:1;s:25:"Nilai Rw yang tidak tepat";i:2;s:28:"Parameter m dan n yang salah";i:3;s:34:"Invasi lumpur yang tidak dikoreksi";}', 'a:4:{i:0;s:20:"Different core color";i:1;s:18:"Incorrect Rw value";i:2;s:24:"Wrong m and n parameters";i:3;s:24:"Uncorrected mud invasion";}', '', 'a:3:{i:0;s:25:"Nilai Rw yang tidak tepat";i:1;s:28:"Parameter m dan n yang salah";i:2;s:34:"Invasi lumpur yang tidak dikoreksi";}', 'a:3:{i:0;s:18:"Incorrect Rw value";i:1;s:24:"Wrong m and n parameters";i:2;s:24:"Uncorrected mud invasion";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000744', 'Manakah informasi yang dapat diperoleh dari analisis crossplot neutron-density?', 'Which information can be obtained from neutron-density crossplot analysis?', 'multi', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:20:"Porositas terkoreksi";i:1;s:22:"Jenis litologi dominan";i:2;s:13:"Kehadiran gas";i:3;s:21:"Kedalaman total sumur";}', 'a:4:{i:0;s:18:"Corrected porosity";i:1;s:23:"Dominant lithology type";i:2;s:15:"Presence of gas";i:3;s:16:"Total well depth";}', '', 'a:3:{i:0;s:22:"Jenis litologi dominan";i:1;s:13:"Kehadiran gas";i:2;s:20:"Porositas terkoreksi";}', 'a:3:{i:0;s:23:"Dominant lithology type";i:1;s:15:"Presence of gas";i:2;s:18:"Corrected porosity";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000745', 'Manakah pernyataan yang benar tentang net pay?', 'Which statements about net pay are correct?', 'multi', 'PFC000000005', 'Final Advanced', 'a:4:{i:0;s:51:"Selalu lebih kecil atau sama dengan gross thickness";i:1;s:35:"Sama dengan ketebalan total formasi";i:2;s:36:"Ditentukan setelah cutoff diterapkan";i:3;s:43:"Mempengaruhi perhitungan volume hidrokarbon";}', 'a:4:{i:0;s:50:"It is always less than or equal to gross thickness";i:1;s:39:"It equals the total formation thickness";i:2;s:42:"It is determined after cutoffs are applied";i:3;s:45:"It affects the hydrocarbon volume calculation";}', '', 'a:3:{i:0;s:36:"Ditentukan setelah cutoff diterapkan";i:1;s:51:"Selalu lebih kecil atau sama dengan gross thickness";i:2;s:43:"Mempengaruhi perhitungan volume hidrokarbon";}', 'a:3:{i:0;s:42:"It is determined after cutoffs are applied";i:1;s:50:"It is always less than or equal to gross thickness";i:2;s:45:"It affects the hydrocarbon volume calculation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000746', 'Urutkan perhitungan dari data log sampai volume hidrokarbon.', 'Arrange the calculation steps from log data to hydrocarbon volume.', 'drag', 'PFC000000005', 'Final Advanced', 'a:6:{i:0;s:26:"Pengukuran laju alir sumur";i:1;s:18:"Vsh dari gamma ray";i:2;s:30:"Porositas dari density/neutron";i:3;s:14:"Sw dari Archie";i:4;s:13:"Tebal net pay";i:5;s:18:"Volume hidrokarbon";}', 'a:6:{i:0;s:26:"Well flow rate measurement";i:1;s:18:"Vsh from gamma ray";i:2;s:29:"Porosity from density/neutron";i:3;s:14:"Sw from Archie";i:4;s:17:"Net pay thickness";i:5;s:18:"Hydrocarbon volume";}', '', 'a:5:{i:0;s:18:"Vsh dari gamma ray";i:1;s:30:"Porositas dari density/neutron";i:2;s:14:"Sw dari Archie";i:3;s:13:"Tebal net pay";i:4;s:18:"Volume hidrokarbon";}', 'a:5:{i:0;s:18:"Vsh from gamma ray";i:1;s:29:"Porosity from density/neutron";i:2;s:14:"Sw from Archie";i:3;s:17:"Net pay thickness";i:4;s:18:"Hydrocarbon volume";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000747', 'Urutkan nilai saturasi air (Sw) dari zona paling produktif ke zona air.', 'Arrange water saturation (Sw) values from the most productive zone to the water zone.', 'drag', 'PFC000000005', 'Final Advanced', 'a:5:{i:0;s:17:"Sw rendah (< 30%)";i:1;s:20:"Sw sedang (30 - 50%)";i:2;s:20:"Sw tinggi (50 - 70%)";i:3;s:20:"Sw 100% (water zone)";i:4;s:17:"Sw negatif (-10%)";}', 'a:5:{i:0;s:14:"Low Sw (< 30%)";i:1;s:22:"Moderate Sw (30 - 50%)";i:2;s:18:"High Sw (50 - 70%)";i:3;s:20:"Sw 100% (water zone)";i:4;s:18:"Negative Sw (-10%)";}', '', 'a:4:{i:0;s:17:"Sw rendah (< 30%)";i:1;s:20:"Sw sedang (30 - 50%)";i:2;s:20:"Sw tinggi (50 - 70%)";i:3;s:20:"Sw 100% (water zone)";}', 'a:4:{i:0;s:14:"Low Sw (< 30%)";i:1;s:22:"Moderate Sw (30 - 50%)";i:2;s:18:"High Sw (50 - 70%)";i:3;s:20:"Sw 100% (water zone)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000748', 'Benarkah zona dengan resistivitas tinggi selalu berarti zona minyak?', 'Is it true that a high-resistivity zone always means an oil zone?', 'yesorno', 'PFC000000005', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000749', 'Benarkah porositas yang dipakai pada persamaan Archie adalah porositas efektif?', 'Is it true that the porosity used in Archie''s equation is effective porosity?', 'yesorno', 'PFC000000005', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
